const SPHINX = "sphinx";

const BASE_SCORE_FOR_THREE_TYPES = 1;
const POINT_FOR_THE_SPHINX_ITSELF = 1;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const scoreForOneSphinx = (): number =>
  BASE_SCORE_FOR_THREE_TYPES + POINT_FOR_THE_SPHINX_ITSELF;

export const scoreArmy = (army: Card[]): number =>
  army.filter(isSphinx).reduce((total) => total + scoreForOneSphinx(), 0);

